// Aceita apenas evento real da Evolution para o contato de teste.
// Um único contato autorizado. Nunca registre credenciais neste código.
// A Central determina quem recebe atendimento. Não manter allowlist duplicada no n8n.
const body = $input.first()?.json?.body;
if (!body || body.instance !== 'umdoislab' || !['messages.upsert','MESSAGES_UPSERT'].includes(String(body.event || ''))) return [];
const data = body.data;
const key = data?.key;
const sender = String(key?.remoteJid || '');
if (key?.fromMe !== false || !/^[0-9]{10,15}@s\.whatsapp\.net$/.test(sender)) return [];
if (!key?.id || typeof key.id !== 'string' || key.id.length > 160) return [];
const message = data?.message || {};
const text = message.conversation
  ?? message.extendedTextMessage?.text
  ?? message.imageMessage?.caption
  ?? message.videoMessage?.caption
  ?? '';
if (typeof text !== 'string' || !text.trim()) return []; // áudio/mídia sem texto: fluxo separado no futuro
const clean = text.trim().slice(0,500);
const t = clean.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const humanRequest = /\b(humano|atendente|falar com (uma )?pessoa|quero atendimento humano|falar com vendedor)\b/.test(t);
let category = 'outros';
if (humanRequest) category = 'atendimento';
else if (/\b(oi|ola|opa|bom dia|boa tarde|boa noite)\b/.test(t)) category = 'saudacao';
else if (/\b(mf ?doom|mfdu|quasimoto|dichavador|tchavador|pracinha)\b/.test(t)) category = 'produto';
else if (/\b(catalogo|catalog)\b/.test(t)) category = 'catalogo';
else if (/\b(preco|valor|quanto|custa)\b/.test(t)) category = 'preco';
else if (/\b(entrega|frete|cep|envio)\b/.test(t)) category = 'entrega';
else if (/\b(pedido|rastreio|compra)\b/.test(t)) category = 'pedido';
return [{json:{
 instance:'umdoislab',isClientMessage:true,isGroup:false,
 senderId:sender,senderName:String(data.pushName || sender.split('@')[0]).slice(0,100),
 messageId:key.id,messageText:clean,category,summary:'Mensagem recebida: '+category,
 handoffRequested:humanRequest
}}];

const d=$input.first()?.json;
const original=$('Validar remetente e classificar').first().json;
if (!d || !['auto','handoff','offer_choice','resume','silent','ignore'].includes(d.action) || d.messageId!==original.messageId || (d.senderId && d.senderId !== original.senderId)) throw Error('Estado da Central inválido; não responder');
return [{json:{...d}}];

const input=$('Validar remetente e classificar').first().json;
const decision=$('Consultar e registrar na Central').first().json;
if (!['auto'].includes(decision.action)) throw Error('Gemini fora do estado automático');
const raw=$input.first()?.json?.content?.parts?.map(p=>p.text||'').join('') || '';
const intent=raw.toLowerCase().trim().replace(/[^a-z]/g,'');
const known=['saudacao','produto','preco','catalogo','entrega','pedido','atendimento','outros'];
const category=known.includes(intent)?intent:'outros';
const replies={
saudacao:'Oi! 😊 Como posso ajudar na Umdoislab?',
catalogo:'Você pode ver nossos produtos em https://umdoislab.com.br/. Quer saber sobre algum produto específico?',
produto:'Posso ajudar com esse produto! Você quer saber preço, características ou disponibilidade?',
preco:'Qual produto você quer consultar? Para confirmar preços, precisamos consultar o catálogo.',
entrega:'Qual é seu CEP e qual produto você procura? Assim podemos verificar a entrega.',
pedido:'Para informações específicas do seu pedido, digite "atendente" para falar com uma pessoa.',
atendimento:'Para falar com uma pessoa da Umdoislab, digite "atendente".',
outros:'Pode me explicar um pouquinho melhor? Assim consigo encaminhar sua dúvida.'
};
return [{json:{instance:input.instance,senderId:input.senderId,messageId:input.messageId,
action:decision.action,shouldSend:true,kind:category==='outros'?'fallback':'normal',
text:replies[category],geminiIntent:category}}];

const state=$input.first().json;
const original=$('Validar remetente e classificar').first().json;
if(!['handoff','offer_choice','resume','silent','ignore'].includes(state.action)) throw Error('Estado protocolar não reconhecido');
const kind=state.action==='handoff'?'handoff':state.action==='offer_choice'?'choice':'normal';
return [{json:{instance:original.instance,senderId:original.senderId,messageId:original.messageId,
 action:state.action,shouldSend:!['silent','ignore'].includes(state.action),kind,
 text:state.action==='resume'?'Certo, podemos continuar pelo atendimento automático. 😊 O que você quer saber?':''}}];
